import { useEffect, useState } from "react";
import { AuthorizeProps } from "../../hocs/auth-aware/auth-aware";
import { buildField, isNonEmptyArray, throwError, useForm } from "@/core/helpers";
import InputField from "@/core/components/primitives/input-field/input-field";
import PhoneOrEmailFields, {
  MethodType,
  createContactField,
} from "@/core/components/primitives/phone-or-email-fields/phone-or-email-fields";
import { useTranslation } from "react-i18next";
import { MyParksService } from "@/core/services";
import { AuthActionTypes } from "@/core/types";
import Banner from "@/core/components/primitives/banner/banner";
import { OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import styles from "./login-or-register.module.less";

const parseApiError = (error: unknown) => {
  const apiErrors =
    typeof error === "object" && ((error as any)?.data?.errors as Array<{ message: string; messageToken: string }>);
  if (!isNonEmptyArray(apiErrors)) {
    return undefined;
  }
  return apiErrors as Array<{ message: string; messageToken: string }>;
};

type LoginOrRegisterState =
  | { step: "enterContact"; contactType: "email" | "phone" }
  | { step: "loginUser"; contactType: "email" | "phone" }
  | { step: "registerUser"; contactType: "email" | "phone" };

export const LoginOrRegister = ({
  notLoggedInMessage,
  auth,
  dispatch,
}: AuthorizeProps & { notLoggedInMessage: string }) => {
  const { t } = useTranslation();

  const [stepState, setStepState] = useState<LoginOrRegisterState>({ step: "enterContact", contactType: "phone" });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<{ message: string; fields?: Array<string> } | null>(null);
  const [phoneOrEmailValue, setPhoneOrEmailValue] = useState<string | undefined>();
  const [selectedDeliveryOption, setSelectedDeliveryOption] = useState<MethodType>("phone");

  const invalidCode = !!error?.fields?.includes("code");

  const [loginCodeForm, , handleLoginCodeChange, , revalidateCode] = useForm({
    fields: new Map([
      [
        "code",
        buildField("code", {
          isRequired: true,
          placeholder: t("authPinPlaceholder"),
          label: t("authPinLabel"),
          autoComplete: "one-time-code",
        }),
      ],
    ]),
  });
  const [registerForm, , handleRegistrationInfoChange, , revalidateRegistrationForm] = useForm({
    fields: new Map([
      [
        "code",
        buildField("code", {
          isRequired: true,
          placeholder: t("authPinPlaceholder"),
          label: t("authPinLabel"),
          autoComplete: "one-time-code",
        }),
      ],
      [
        "firstName",
        buildField("firstName", {
          isRequired: true,
          placeholder: t("firstName"),
          label: t("firstName"),
          autoComplete: "given-name",
        }),
      ],
      [
        "lastName",
        buildField("lastName", {
          isRequired: true,
          placeholder: t("lastName"),
          label: t("lastName"),
          autoComplete: "family-name",
        }),
      ],
    ]),
  });

  const phoneFieldName = "phoneNumber";
  const emailFieldName = "emailAddress";
  const phoneField = createContactField({ fieldType: "phone", name: phoneFieldName, placeholder: "phone", t }).field;
  const emailField = createContactField({ fieldType: "email", name: emailFieldName, placeholder: "email", t }).field;
  const [contactForm, , handleContactChange, , validateContactForm, , focusOnContactField] = useForm(
    {
      fields: new Map<string, typeof phoneField>().set(phoneField.name, phoneField).set(emailField.name, emailField),
    },
    true,
  );

  const cancelPinStep = async () => {
    setStepState({ step: "enterContact", contactType: "phone" });
    setIsLoading(true);
    try {
      // If we have an ongoing login attempt, cancel it
      if (auth.cookieString) await MyParksService.deleteSession();
    } finally {
      setIsLoading(false);
      dispatch({ type: AuthActionTypes.SESSION_DELETED });
    }
  };

  // If we reach this step with an ongoing login attempt, cancel it
  useEffect(() => {
    if (auth.cookieString) {
      cancelPinStep();
    }
    // This should only run once on mount, when we enter this component
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Clear any existing errors when changing step
  useEffect(() => {
    setError(null);
  }, [stepState.step]);

  if (stepState.step === "enterContact") {
    // First attempts a login. If that fails, starts registration flow
    const submitContact = async () => {
      if (isLoading) return;
      const { isFormValid } = validateContactForm();
      if (!isFormValid) {
        focusOnContactField("FIRST_INVALID");
        return;
      }

      setIsLoading(true);
      const contact =
        selectedDeliveryOption === "phone"
          ? contactForm.fields.get(phoneFieldName)?.value
          : contactForm.fields.get(emailFieldName)?.value;
      if (!contact) {
        setIsLoading(false);
        return;
      }
      setPhoneOrEmailValue(contact);

      try {
        const response = await MyParksService.initiateSession(contact);
        setStepState({ step: "loginUser", contactType: selectedDeliveryOption });
        const responseInfo = {
          antiCsrfToken: response.antiCsrfToken,
          cookieString: response.cookieString,
          isLoggedIn: response.hasLoggedIn,
          loginMethod: response.loginMethod,
        };
        dispatch({ type: AuthActionTypes.SESSION_CREATED, payload: responseInfo });
      } catch (error) {
        const apiErrors = parseApiError(error);
        const isNewUserError = ["Session/NoSuchUser/PhoneNo", "Session/NoSuchUser/Email"].some(
          (token) => apiErrors?.some((e) => e.messageToken === token),
        );
        if (!isNewUserError) {
          throw error;
        }
        await MyParksService.postContactInformationForVerification({
          contact,
        });
        setStepState({ step: "registerUser", contactType: selectedDeliveryOption });
      } finally {
        setIsLoading(false);
      }
    };

    return (
      <div>
        <p className="heading-xs">{t("authNotLoggedIn")}</p>
        <p>{notLoggedInMessage}</p>
        <div className={styles.contactMode}>
          <PhoneOrEmailFields
            form={contactForm}
            method={selectedDeliveryOption}
            radioGroupName="deliveryMethod"
            radioGroupLabel="phoneOrEmailFieldsRadioGroupLabel"
            radioLabelPhone="textMessage"
            phoneFieldName={phoneFieldName}
            emailFieldName={emailFieldName}
            onMethodChange={(_, method) => setSelectedDeliveryOption(method)}
            onContactChange={(name, value) => handleContactChange(name, value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") submitContact();
            }}
          />
        </div>
        <div className={styles.buttonRow}>
          {!isLoading ? (
            <PrimaryButton label={t("authSendPin")} onClick={submitContact} isFullWidth />
          ) : (
            <PrimaryButton iconCenterNew="loading" ariaLabel={t("loading")} isFullWidth isDisabled />
          )}
        </div>
      </div>
    );
  }
  if (stepState.step === "loginUser") {
    const submitCode = async () => {
      const code = loginCodeForm.fields.get("code")?.value;
      const validationError = revalidateCode();
      if (!code || isLoading || !validationError.isFormValid) return;

      setError(null);
      setIsLoading(true);
      try {
        const response = await MyParksService.postVerificationCode(code);
        const responseInfo = {
          antiCsrfToken: response.antiCsrfToken,
          cookieString: response.cookieString,
          isLoggedIn: response.hasLoggedIn,
          user: response.user,
        };
        dispatch({ type: AuthActionTypes.SESSION_UPDATED, payload: responseInfo });
      } catch (error) {
        const apiErrors = parseApiError(error);
        const fieldErrors = apiErrors?.some((e) => e.messageToken === "Session/InvalidPin") ? ["code"] : undefined;
        setError({ message: apiErrors?.[0]?.message || t("somethingWentWrong"), fields: fieldErrors });
      } finally {
        setIsLoading(false);
      }
    };

    return (
      <div>
        <p className="heading-xs">{t("authPinHeader")}</p>
        {error && (
          <Banner
            type="critical"
            heading={invalidCode ? t("authInvalidPin") : t("somethingWentWrong")}
            paragraph={error.message}
          />
        )}
        <p>{t("authPinInstructions", [phoneOrEmailValue || t(selectedDeliveryOption)])}</p>
        <InputField
          formField={loginCodeForm.fields.get("code") ?? throwError("Missing code field")}
          inputMode="numeric"
          onChange={handleLoginCodeChange}
          onKeyDown={(e) => {
            if (e.key === "Enter") submitCode();
          }}
          focus
        />
        <div className={styles.buttonRow}>
          <OutlineButton label={t("back")} onClick={cancelPinStep} isFullWidth />
          {!isLoading ? (
            <PrimaryButton label={t("login")} onClick={submitCode} isFullWidth />
          ) : (
            <PrimaryButton iconCenterNew="loading" ariaLabel={t("loading")} isFullWidth isDisabled />
          )}
        </div>
      </div>
    );
  }

  const submitRegister = async () => {
    const firstName = registerForm.fields.get("firstName")?.value;
    const lastName = registerForm.fields.get("lastName")?.value;
    const contact =
      phoneOrEmailValue ||
      (selectedDeliveryOption === "phone"
        ? contactForm.fields.get(phoneFieldName)?.value
        : contactForm.fields.get(emailFieldName)?.value);
    const codeField = registerForm.fields.get("code");
    const code = codeField?.value;
    const validationError = revalidateRegistrationForm();
    if (!firstName || !lastName || !contact || !code || isLoading || !validationError.isFormValid) return;

    setError(null);
    setIsLoading(true);
    try {
      const response = await MyParksService.registerUser(
        {
          firstName,
          lastName,
          contact,
        },
        code,
      );
      const responseInfo = {
        antiCsrfToken: response.antiCsrfToken,
        cookieString: response.cookieString,
        isLoggedIn: response.hasLoggedIn,
        user: response.user,
      };
      dispatch({ type: AuthActionTypes.SESSION_UPDATED, payload: responseInfo });
    } catch (error) {
      const apiErrors = parseApiError(error);
      const fieldErrors = apiErrors?.some((e) => e.messageToken === "AccountRegistration/BadContactVerification")
        ? ["code"]
        : undefined;
      setError({ message: apiErrors?.[0]?.message || t("somethingWentWrong"), fields: fieldErrors });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div>
      <p className="heading-xs">{t("authRegisterHeading")}</p>
      <p>{t("authRegisterInstructions")}</p>
      {error && (
        <Banner
          type="critical"
          heading={invalidCode ? t("authInvalidPin") : t("somethingWentWrong")}
          paragraph={error.message}
        />
      )}
      <InputField
        formField={registerForm.fields.get("code") ?? throwError("Missing code field")}
        inputMode="numeric"
        onChange={handleRegistrationInfoChange}
        onKeyDown={(e) => {
          if (e.key === "Enter") submitRegister();
        }}
        helperText={t("authPinInstructions", [phoneOrEmailValue || t(selectedDeliveryOption)])}
        focus
      />
      <InputField
        formField={registerForm.fields.get("firstName") ?? throwError("Missing firstName field")}
        maxLength={50} // This is a constraint from the backend
        onChange={handleRegistrationInfoChange}
        onKeyDown={(e) => {
          if (e.key === "Enter") submitRegister();
        }}
      />
      <InputField
        formField={registerForm.fields.get("lastName") ?? throwError("Missing lastName field")}
        maxLength={50} // This is a constraint from the backend
        onChange={handleRegistrationInfoChange}
        onKeyDown={(e) => {
          if (e.key === "Enter") submitRegister();
        }}
      />
      <div className={styles.buttonRow}>
        <OutlineButton label={t("back")} onClick={cancelPinStep} isDisabled={isLoading} isFullWidth />
        {!isLoading ? (
          <PrimaryButton label={t("authRegisterSubmit")} onClick={submitRegister} isFullWidth />
        ) : (
          <PrimaryButton iconCenterNew="loading" ariaLabel={t("loading")} isFullWidth isDisabled />
        )}
      </div>
    </div>
  );
};
