import { Meta, StoryObj } from "@storybook/react";
import { LoginOrRegister } from "./login-or-register";
import { AuthContextProvider } from "@/core/auth";
import AuthAware from "../../hocs/auth-aware/auth-aware";
import { useState } from "react";
import { MyParksService } from "@/core/services";
import { exhaustiveCheck } from "@/core/helpers";
import { action } from "storybook/actions";
import { AuthActionTypes, IUser } from "@/core/types";
import { expect, userEvent, waitFor, within } from "storybook/test";

const AuthAwareComponent = AuthAware<{ notLoggedInMessage: string }>((props) => {
  if (props.auth.isLoggedIn) {
    return (
      <div>
        <h3>
          This view should be defined by the parent, not <code>LoginOrRegister</code>
        </h3>
        Logged in as {props.auth.user?.firstName} {props.auth.user?.lastName} (
        {props.auth.user?.email || props.auth.user?.phoneNo})
        <br />
        <button
          onClick={() => {
            MyParksService.deleteSession();
            props.dispatch({ type: AuthActionTypes.SESSION_DELETED });
          }}
        >
          Log out
        </button>
      </div>
    );
  }
  return <LoginOrRegister {...props} />;
});

const emailUserSession = {
  antiCsrfToken: "mocked-token",
  cookieString: "email-session-cookie",
  hasLoggedIn: true,
  user: {
    altId: "user-email",
    email: "user@example.com",
    phoneNo: "",
    firstName: "Email",
    lastName: "User",
    birthDate: "1990-01-01",
  } satisfies IUser,
};
const phoneUserSession = {
  antiCsrfToken: "mocked-token",
  cookieString: "phone-session-cookie",
  hasLoggedIn: true,
  user: {
    altId: "user-phone",
    email: "",
    phoneNo: "0709912345",
    firstName: "Phone",
    lastName: "User",
    birthDate: "1990-01-01",
  } satisfies IUser,
};
const verificationCode = "999999";

const meta = {
  title: "Modules/Login or Register",
  component: AuthAwareComponent,
  args: {
    notLoggedInMessage: "You are not logged in",
  },
  render: function AComponent(args) {
    const [loggedInAs, setLoggedInAs] = useState<"loggedOut" | "email" | "phone">("loggedOut");
    MyParksService.fetchSession = async () => {
      await new Promise((resolve) => setTimeout(resolve, 500));
      action("fetchSession called")({ loggedInAs });
      if (loggedInAs === "loggedOut") {
        throw new Error("No session");
      } else if (loggedInAs === "email") {
        return emailUserSession;
      } else if (loggedInAs === "phone") {
        return phoneUserSession;
      }
      exhaustiveCheck(loggedInAs);
      throw new Error("Unrecognized loggedInAs value");
    };
    MyParksService.fetchProducts = async () => {
      await new Promise((resolve) => setTimeout(resolve, 500));
      action("fetchProducts called")();
      return {
        seasonPasses: [],
        reactivatableSeasonPasses: [],
        entryTickets: [],
        attractionTickets: [],
        activityPasses: [],
        standardProducts: [],
        bookableProducts: [],
        giftCards: [],
        webOrders: [],
        looseRows: [],
        parkingPermits: [],
        parkingProducts: [],
        contactless: { visitors: [] },
        cookieString: loggedInAs === "email" ? "email-session-cookie" : "phone-session-cookie",
      };
    };
    MyParksService.initiateSession = async (contactMethod: string) => {
      await new Promise((resolve) => setTimeout(resolve, 500));
      action("initiateSession called")({ contactMethod });
      if (contactMethod === emailUserSession.user.email) {
        setLoggedInAs("email");
        return {
          antiCsrfToken: "mocked-token",
          cookieString: "email-session-cookie",
          hasLoggedIn: false,
          loginMethod: "email",
        };
      } else if (contactMethod === phoneUserSession.user.phoneNo) {
        setLoggedInAs("phone");
        return {
          antiCsrfToken: "mocked-token",
          cookieString: "phone-session-cookie",
          hasLoggedIn: false,
          loginMethod: "phone",
        };
      }
      throw {
        data: {
          errors: [
            {
              message: "No user found with that contact method",
              messageToken: contactMethod.includes("@") ? "Session/NoSuchUser/Email" : "Session/NoSuchUser/PhoneNo",
            },
          ],
        },
      };
    };
    MyParksService.postVerificationCode = async (code: string) => {
      await new Promise((resolve) => setTimeout(resolve, 500));
      action("postVerificationCode called")({ code, loggedInAs });
      if (code !== verificationCode) {
        throw {
          data: {
            errors: [
              {
                message: "(From backend) Invalid verification code",
                messageToken: "Session/InvalidPin",
              },
            ],
          },
        };
      } else if (loggedInAs === "email") {
        return emailUserSession;
      } else if (loggedInAs === "phone") {
        return phoneUserSession;
      }
      throw new Error("No session");
    };
    MyParksService.postContactInformationForVerification = async ({ contact }: { contact: string }) => {
      await new Promise((resolve) => setTimeout(resolve, 500));
      action("postContactInformationForVerification called")({ contact });
      return {};
    };
    MyParksService.registerUser = async (userDetails, code) => {
      await new Promise((resolve) => setTimeout(resolve, 500));
      action("registerUser called")({ userDetails, code, loggedInAs });
      if (code !== verificationCode) {
        throw {
          data: {
            errors: [
              {
                message: "(From backend) Invalid verification code",
                messageToken: "AccountRegistration/BadContactVerification",
              },
            ],
          },
        };
      }
      if (userDetails.contact.includes("@")) {
        setLoggedInAs("email");
        return emailUserSession;
      } else {
        setLoggedInAs("phone");
        return phoneUserSession;
      }
    };
    MyParksService.deleteSession = async () => {
      await new Promise((resolve) => setTimeout(resolve, 500));
      action("deleteSession called")();
      setLoggedInAs("loggedOut");
      return {} as any;
    };

    return (
      <AuthContextProvider>
        <AuthAwareComponent {...args} />
        <hr />
        <p>
          There are two mocked users you can log in as:
          <ul>
            <li>
              <strong>Email</strong>: {emailUserSession.user.email}
            </li>
            <li>
              <strong>Phone</strong>: {phoneUserSession.user.phoneNo}
            </li>
          </ul>
          To try registering a new user, use any other email or phone number. (but you will end up logged in as the
          mocked user for your contact method)
        </p>
        <p>
          In all cases, use {verificationCode} as the verification code. (Or any other number to trigger an error state)
        </p>
      </AuthContextProvider>
    );
  },
} satisfies Meta<typeof AuthAwareComponent>;

export default meta;

type Story = StoryObj<typeof meta>;

export const LoggedOut = {} satisfies Story;

export const LoggingInWithPhone: Story = {
  play: async ({ canvasElement }) => {
    // Act
    const input = await within(canvasElement).findByPlaceholderText("Telefonnummer");

    await userEvent.type(input, phoneUserSession.user.phoneNo, { delay: 50 });
    await userEvent.keyboard("{Enter}", { delay: 50 });

    // Assert
    const codeInput = await waitFor(async () => {
      const codeInput = await within(canvasElement).findByPlaceholderText("123456");
      expect(codeInput).toBeInTheDocument();
      return codeInput;
    });
    // Only the code input should be visible
    canvasElement.querySelectorAll("input").forEach((input) => {
      expect(input).toBe(codeInput);
    });
  },
};

export const RegisteringWithPhone: Story = {
  play: async ({ canvasElement }) => {
    // Act
    const input = await within(canvasElement).findByPlaceholderText("Telefonnummer");

    await userEvent.type(input, "0701111111", { delay: 50 });
    await userEvent.keyboard("{Enter}", { delay: 50 });

    // Assert
    const allowedInputs = await waitFor(
      async () => {
        const codeInput = await within(canvasElement).findByPlaceholderText("123456");
        expect(codeInput).toBeInTheDocument();
        const firstNameInput = await within(canvasElement).findByPlaceholderText("Förnamn");
        expect(firstNameInput).toBeInTheDocument();
        const lastNameInput = await within(canvasElement).findByPlaceholderText("Efternamn");
        expect(lastNameInput).toBeInTheDocument();
        return [codeInput, firstNameInput, lastNameInput];
      },
      { timeout: 2_000 },
    );
    // Only the registration inputs should be visible
    canvasElement.querySelectorAll("input").forEach((input) => {
      expect(allowedInputs).toContain(input);
    });
  },
};
